/// A social link type's mark (SocialLinks SOCIAL_META), if it has one.
pub fn social(link_type: &str) -> Option<&'static Icon> {
    Some(match link_type {
        "TWITTER" => &TWITTER,
        "INSTAGRAM" => &INSTAGRAM,
        "TIKTOK" => &TIKTOK,
        "FACEBOOK" => &FACEBOOK,
        "SNAPCHAT" => &SNAPCHAT,
        _ => return None,
    })
}

/// `icon` at `size` points in `c`, decorative.
pub fn mark(icon: &'static Icon, size: f32, c: rune::Color) -> El {
    rune::icon(icon, size).color(c).a11y_hidden()
}

/// ListenBrainz's two-tone mark: the accent faces under the text-coloured lines.
pub fn listenbrainz(size: f32, accent: rune::Color, ink: rune::Color) -> El {
    rune::el().size(size, size).a11y_hidden()
        .child(rune::icon(&LISTENBRAINZ_ACCENT, size).color(accent).absolute(0.0, 0.0))
        .child(rune::icon(&LISTENBRAINZ_INK, size).color(ink).absolute(0.0, 0.0))
}
